#include <stdio.h>

int idg = 93;
unsigned int uflag = 5562;
short int strv = -8;

__attribute__((noinline)) void report(int token) {
    printf("token=%d\n", token);
}

__attribute__((noinline)) int work(void) {
    int acc = 2771;
    for (int i = 0; i < 15; i++) {
        acc = acc * 3 + i;
        if (i == 7) uflag = (unsigned int)(acc ^ 0x4167u);
    }
    idg = acc % 2981;
    strv = (short)(acc & 0x7f);
    report(acc);
    return acc;
}

int main(void) {
    return work() % 5;
}
